import 'package:flutter/material.dart';
import 'package:lazerus_core/lazerus_core.dart';

import '../../../../../core/macros/triggers/microphone/microphone_mono_audio_trigger.dart';
import '../macro_editor_node_module.dart';

final class MicrophoneMacroEditorNodeModule extends MacroEditorNodeModule
    implements MacroEditorStarterNodeModule {
  @override
  String get kind => MicrophoneMonoAudioTriggerFactory.moduleKind;

  @override
  MacroEditorStarterRole get starterRole => MacroEditorStarterRole.source;

  @override
  Iterable<MacroEditorPaletteEntry> paletteEntries(
    MacroEditorNodePresentationState state,
  ) => <MacroEditorPaletteEntry>[
    const MacroEditorPaletteEntry(
      id: 'palette.microphone',
      moduleKind: MicrophoneMonoAudioTriggerFactory.moduleKind,
      section: MacroEditorPaletteSection.modules,
      icon: Icons.mic_none_outlined,
      title: 'Microphone',
      subtitle: 'Mono audio input',
    ),
  ];

  @override
  MacroNode createStarterNode({required MacroEditorNewId newId}) =>
      _createNode(newId());

  @override
  MacroNode? createNode(
    MacroEditorPaletteEntry entry, {
    required MacroEditorNewId newId,
  }) => _createNode(newId());

  @override
  Widget buildInspector(
    BuildContext context,
    MacroEditorNodeViewContext nodeContext,
  ) => MacroEditorNodeInspectorCard(
    icon: Icons.mic_none_outlined,
    title: titleFor(nodeContext.node),
    enabled: nodeContext.state.enabled,
    onRemove: nodeContext.removeNode,
    child: Column(
      crossAxisAlignment: CrossAxisAlignment.start,
      children: <Widget>[
        const Text(
          'Microphone input is transient and is not written to files.',
        ),
        const SizedBox(height: 12),
        _MicrophoneDbMeter(
          dbfs: nodeContext.state.runtime?.lastTelemetry?.inputLevelDbfs,
        ),
      ],
    ),
  );

  MacroNode _createNode(String id) => MacroNode(
    id: id,
    kind: kind,
    displayName: 'Microphone',
    ports: <MacroPortDeclaration>[
      MacroPortDeclaration(
        id: '$id.${MicrophoneMonoAudioTriggerFactory.audioPortId}',
        direction: MacroPortDirection.output,
        type: MacroPortType.triggerMonoAudio,
        displayIdentifier: 'microphone.audio',
        displayName: 'Microphone audio',
      ),
    ],
  );
}

/// UI-only meter; it receives one derived dBFS scalar and never retains PCM.
final class _MicrophoneDbMeter extends StatelessWidget {
  const _MicrophoneDbMeter({required this.dbfs});

  final double? dbfs;

  @override
  Widget build(BuildContext context) {
    final value = dbfs;
    final label = value == null
        ? 'Очікування аудіо'
        : '${value.toStringAsFixed(1)} dBFS';
    return Semantics(
      label: 'Microphone input level: $label',
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: <Widget>[
          Row(
            children: <Widget>[
              Text(
                'Input level',
                style: Theme.of(context).textTheme.labelLarge,
              ),
              const Spacer(),
              Text(label, style: Theme.of(context).textTheme.labelLarge),
            ],
          ),
          const SizedBox(height: 6),
          RepaintBoundary(
            child: SizedBox(
              height: 52,
              width: double.infinity,
              child: CustomPaint(painter: _MicrophoneDbMeterPainter(value)),
            ),
          ),
        ],
      ),
    );
  }
}

final class _MicrophoneDbMeterPainter extends CustomPainter {
  const _MicrophoneDbMeterPainter(this.dbfs);

  final double? dbfs;

  static const _minimumDbfs = -72.0;

  @override
  void paint(Canvas canvas, Size size) {
    const labelSpace = 17.0;
    final meter = RRect.fromRectAndRadius(
      Rect.fromLTWH(0, 0, size.width, size.height - labelSpace),
      const Radius.circular(8),
    );
    canvas.drawRRect(meter, Paint()..color = const Color(0xFF181825));
    final active = dbfs?.clamp(_minimumDbfs, 0.0).toDouble();
    if (active != null) {
      final width = size.width * ((active - _minimumDbfs) / -_minimumDbfs);
      final activeMeter = RRect.fromRectAndRadius(
        Rect.fromLTWH(0, 0, width, size.height - labelSpace),
        const Radius.circular(8),
      );
      canvas.drawRRect(
        activeMeter,
        Paint()
          ..shader = const LinearGradient(
            colors: <Color>[
              Color(0xFF89B4FA),
              Color(0xFFA6E3A1),
              Color(0xFFF9E2AF),
              Color(0xFFF38BA8),
            ],
          ).createShader(meter.outerRect),
      );
      final x = width.clamp(1.0, size.width - 1.0).toDouble();
      canvas.drawLine(
        Offset(x, 0),
        Offset(x, size.height - labelSpace),
        Paint()
          ..color = Colors.white
          ..strokeWidth = 1.5,
      );
    }
    final tickPaint = Paint()
      ..color = const Color(0xFFBAC2DE)
      ..strokeWidth = 1;
    for (final tick in <int>[-72, -60, -48, -36, -24, -12, 0]) {
      final x = size.width * ((tick - _minimumDbfs) / -_minimumDbfs);
      canvas.drawLine(
        Offset(x, size.height - labelSpace),
        Offset(x, size.height - labelSpace + 4),
        tickPaint,
      );
      final text = TextPainter(
        text: TextSpan(
          text: '$tick',
          style: const TextStyle(color: Color(0xFFBAC2DE), fontSize: 10),
        ),
        textDirection: TextDirection.ltr,
      )..layout();
      text.paint(
        canvas,
        Offset(
          (x - text.width / 2).clamp(0.0, size.width - text.width),
          size.height - 12,
        ),
      );
    }
  }

  @override
  bool shouldRepaint(covariant _MicrophoneDbMeterPainter oldDelegate) =>
      oldDelegate.dbfs != dbfs;
}
